import { normalizeBasePath } from '@mintlify/common';
import fse from 'fs-extra';
import path from 'path';
import { walkFiles } from './export-assets.js';
const CHUNK_BASE_PATH_PATTERN = /(?<=[=(,:]\s*)(["'])\/_next\//g;
const NEXT_STATIC_IN_PAYLOAD_PATTERN = /(?<!\\)"\/_next\/static\//g;
const NEXT_STATIC_IN_HTML_PATTERN = /(?<!\\)(\\?)"\/_next\/static\//g;
const BASE_PATH_PATTERN = /^(\/[\w-]+)+$/;
export function normalizeExportBasePath(value) {
    const basePath = normalizeBasePath(value?.trim());
    if (basePath && !BASE_PATH_PATTERN.test(basePath)) {
        throw new Error(`invalid base path: ${value}`);
    }
    return basePath;
}
export const findBasePathConflict = (routes, basePath) => basePath
    ? routes.find((route) => route === basePath || route.startsWith(`${basePath}/`))
    : undefined;
export const prefixNextAssetPaths = (source, basePath) => source.replace(CHUNK_BASE_PATH_PATTERN, (_match, quote) => `${quote}${basePath}/_next/`);
export const prefixNextStaticPathsInPayload = (payload, basePath) => payload.replace(NEXT_STATIC_IN_PAYLOAD_PATTERN, `"${basePath}/_next/static/`);
export const prefixNextStaticPaths = (html, basePath) => html.replace(NEXT_STATIC_IN_HTML_PATTERN, `$1"${basePath}/_next/static/`);
export async function applyBasePathToExport(exportDir, basePath) {
    const nextStaticDir = path.join(exportDir, '_next', 'static');
    if (!basePath || !(await fse.pathExists(nextStaticDir)))
        return;
    for await (const file of walkFiles(exportDir)) {
        if (file.endsWith('.html') || path.basename(file) === 'index.txt') {
            const source = await fse.readFile(file, 'utf8');
            const patched = file.endsWith('.html')
                ? prefixNextStaticPaths(source, basePath)
                : prefixNextStaticPathsInPayload(source, basePath);
            if (patched !== source)
                await fse.writeFile(file, patched, 'utf8');
            continue;
        }
        if (!file.startsWith(nextStaticDir + path.sep) || !file.endsWith('.js'))
            continue;
        const source = await fse.readFile(file, 'utf8');
        const patched = prefixNextAssetPaths(source, basePath);
        if (patched !== source)
            await fse.writeFile(file, patched, 'utf8');
    }
}
